public class Schedule {

    public enum Day { MON, TUE, WED, THU, FRI, SAT, SUN }

    public static boolean isWeekend(Day d) {
        return d == Day.SAT || d == Day.SUN;
    }

    public static Day next(Day d) {
        Day[] all = Day.values();
        return all[(d.ordinal() + 1) % all.length];
    }
}
